"""Generate measured findings without changing the predeclared parameter choices."""
import csv,gzip,json
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parent
def main():
    data=json.loads(gzip.decompress((ROOT/'dashboard_data.json.gz').read_bytes()));ds=np.array(data['ds']);taus=np.array(data['taus']);follow=json.loads((ROOT/'followups.json').read_text());checks=json.loads((ROOT/'verification.json').read_text());eq=json.loads((ROOT/'fixed_equilibria.json').read_text())
    records=[];lines=['# V6 results · simulation data','',f"Run `{data['run_id']}`. The predeclared factorial contains 9,504 isolated-population trajectories and 9,504 conditional rare-mutant trajectories (12 contexts × 99 trait pairs × 8 environmental histories), plus 75 pilot trajectories. Independent held-out paths add 144 population and 144 mutant trajectories. Fixed-environment controls cover 27 representative trait/plasticity settings. These are conditional models, not fitted biological estimates.",'','## Best observed grid cells, not established evolutionary equilibria','','Maxima use post-burn-in mean abundance, not raw net births minus deaths. All other parameters and each random history are fixed within a context. The table reports a range if cells are numerically tied. Eight histories do not establish a unique stochastic optimum. Conditional invasion uses a common resident (d=.5, τ=3); its best mutant is not an ESS.','','| Adult encoding η_A | Flip hazard κ | Abundance-max d | Abundance-max τ | Mean N | d boundary? | τ boundary? | Best relative-invasion d | Best relative-invasion τ |','|---|---|---|---|---|---|---|---|---|']
    for c in data['contexts']:
        def best(key):
            v=np.array(c['metrics'][key],float);top=np.nanmax(v);ii=np.flatnonzero(np.abs(v-top)<=1e-9*max(1,abs(top)))
            return ii,top
        ii,top=best('mean_N');jj,rate=best('invasion_relative');di,ti=divmod(int(ii[0]),len(taus));jd,jt=divmod(int(jj[0]),len(taus))
        dset=sorted(set(float(ds[int(i)//len(taus)]) for i in ii));tset=sorted(set(float(taus[int(i)%len(taus)]) for i in ii));db=any(x in (0.,1.) for x in dset);tb=any(x in (float(taus[0]),float(taus[-1])) for x in tset)
        row={'eta_A':c['eta_A'],'kappa':c['kappa'],'d_max':dset,'tau_max':tset,'N_max':top,'d_boundary':db,'tau_boundary':tb,'invasion_d_max':float(ds[jd]),'invasion_tau_max':float(taus[jt]),'invasion_max':rate,'invasion_tied_cells':len(jj),'abundance_tied_cells':len(ii)};records.append(row)
        fmt=lambda a:', '.join(f'{x:.5g}' for x in a)
        lines.append(f"| {c['eta_A']} | {c['kappa']} | {fmt(dset)} | {fmt(tset)} | {top:.3f} | {'yes' if db else 'no'} | {'yes' if tb else 'no'} | {ds[jd]:.4g} | {taus[jt]:.4g} |")
    lines+=['', 'No context had both abundance-maximizing parameters in the interior: d=1 was the upper-boundary maximum in all 12 contexts. With adult η_A=.1, the abundance-maximizing grid τ decreases from about 3.366 at κ=0 to .5 at κ=.2. Stable abundance and conditional invasion favor different sampled maturation times; neither is a demonstrated ESS.', '']
    lines+=['','## Held-out matched contrasts at τ=3, adult η_A=.1','','Each contrast reuses the same environmental path for d=0 and d=1. SE describes Monte Carlo path variation, not invented uncertainty for a deterministic equation.','','| κ | Mean N at d=0 | Mean N at d=.5 | Mean N at d=1 | N(d=1)−N(d=0) | Paired SE (16 new paths) |','|---|---|---|---|---|---|']
    held=[]
    for k in [0.,.01,.2]:
        a=np.array([r['mean_N'] for r in follow['held_out'] if r['kappa']==k]);mean=a.mean(0);diff=a[:,2]-a[:,0];se=diff.std(ddof=1)/4
        held.append({'kappa':k,'mean_N':mean.tolist(),'delta_1_minus_0':float(diff.mean()),'paired_SE':float(se)})
        lines.append(f'| {k} | {mean[0]:.3f} | {mean[1]:.3f} | {mean[2]:.3f} | {diff.mean():.3f} | {se:.3f} |')
    cohort=[(x['eta_A'],x['first_accuracy_75']) for x in follow['cohort']]
    lines+=['','## Retention, adaptation and fixed environments','',f"In an adult-only cohort with no births or deaths, the first post-reversal time at which accuracy reaches .75 is {cohort[0][1]} (censored through time 200) for η_A=0, {cohort[1][1]} for η_A=.1, and {cohort[2][1]} for η_A=1. This directly checks the imposed encoding mechanism; it is not evidence that genetic selection produced rigidity. Frozen-adult populations can still adapt through demographic replacement, unlike this fixed cohort.",'',f"All {sum(r['equilibrium_confirmed'] for r in eq['rows'])}/{len(eq['rows'])} representative fixed-environment settings meet the full relative residual criterion 1e-8. The maximum residual is {max(r['full_relative_residual'] for r in eq['rows']):.3g}. Opposite truth signs have equal equilibrium abundance and mirrored cognitive states by symmetry; measured mirrored-RHS errors are at most {max(r['mirror_rhs_error'] for r in eq['rows']):.3g}. This is an informative null result, not a reason to alter environmental payoffs.",'','With κ>0, population and culture fluctuate and are summarized over times 200–600. Different hazards need not have different true invariant equilibria, and this finite run does not prove mixing or uniqueness. Recovery is censored at the next flip; short episodes can have no sampled recovery observation. Inspect recovery fraction alongside conditional recovery time.','','## Numerical and scientific limits','',f"{len(checks['checks'])}/{len(checks['checks'])} numerical/model checks pass. Maximum scaled RK4 error against segment-wise DOP853 is {max(x['max_scaled'] for x in checks['errors']):.3g}; timestep halving is recorded per case in verification.json. A fine-observation check on an independent fast-changing history changes mean N by at most {follow['observation_resolution']['mean_N']['max_abs_difference']:.4g} density units and average adult accuracy by {follow['observation_resolution']['adult_accuracy']['max_abs_difference']:.4g}. This is output-sampling error, separate from solver error.",'','Mathematical consequences: maturation conserves individuals and learned state; zero payoff consequences remove demographic effects of deference/learning; κ=0 removes environmental seed variation; truth reversal preserves demographic symmetry.','','Assumption-sensitive findings: any retention/adaptation tradeoff depends on the prescribed plasticity, finite unit-step memory, signal rate/quality, environmental hazard and error-associated demographic rates. Deference still bundles public substitution and social storage; ordinary social information transfer can explain benefits. There is no newly evolved dogmatism parameter or empirical test of historical childhood. Encoding thinning is algebraically an effective update-rate change.','','Unsupported claims: a proven stationary distribution, a general interior optimum, fixation, an ESS, novelty relative to all cultural-evolution research, or validation of an evolved childhood obedience adaptation.','']
    (ROOT.parent/'results.md').write_text('\n'.join(lines))
    (ROOT/'findings_summary.json').write_text(json.dumps({'label':'simulation data','grid_maxima':records,'heldout':held,'cohort_recovery':cohort,'both_abundance_parameters_interior':[r for r in records if not r['d_boundary'] and not r['tau_boundary']]},indent=2)+'\n')
    print(json.dumps({'both_interior':sum(not r['d_boundary'] and not r['tau_boundary'] for r in records),'contexts':len(records),'heldout':held},indent=2))
if __name__=='__main__':main()
